public static String sortStringsByLength(String input) {
    return Arrays.stream(input.split("\s+")).sorted(Comparator.comparingInt(String::length)).collect(Collectors.joining(" "));
 }

public static String sortStringsByLength(String input) {
    List<String> words = new ArrayList<>(Arrays.asList(input.split("\s+"))); words.sort(Comparator.comparingInt(String::length)); return String.join(" ", words);
 }

